program = '''def transform(grid):
    h = len(grid)
    w = len(grid[0])
    # The two solid border arms identify the L and its inward normal.
    edges = {
        'top': all(grid[0][c] == grid[0][0] for c in range(w)),
        'bottom': all(grid[h-1][c] == grid[h-1][0] for c in range(w)),
        'left': all(grid[r][0] == grid[0][0] for r in range(h)),
        'right': all(grid[r][w-1] == grid[0][w-1] for r in range(h)),
    }
    line = grid[0][0]
    fill = next(v for row in grid for v in row if v != line)
    out = [[8] * w for _ in range(h)]
    vertical = 'left' if edges['left'] else 'right'
    horizontal = 'top' if edges['top'] else 'bottom'
    vx = 0 if vertical == 'left' else w - 1
    hy = 0 if horizontal == 'top' else h - 1
    sx = 1 if vertical == 'left' else -1
    sy = 1 if horizontal == 'top' else -1
    # Original L in the field color, without its corner.
    for r in range(h):
        if r != hy:
            out[r][vx] = fill
    for c in range(w):
        if c != vx:
            out[hy][c] = fill
    # A 45-degree line from the L corner, without either endpoint.
    r, c = hy, vx
    diagonal = []
    while 0 <= r < h and 0 <= c < w:
        diagonal.append((r, c))
        r += sy if horizontal == 'bottom' else 1
        c += sx
    for r, c in diagonal[1:-1]:
        out[r][c] = fill
    # The L translated one cell inward, also without its corner.
    nvx, nhy = vx + sx, hy + sy
    for r in range(h):
        if r != nhy and ((horizontal == 'top' and r > hy) or (horizontal == 'bottom' and r < hy)):
            out[r][nvx] = line
    for c in range(w):
        if c != nvx and ((vertical == 'left' and c > vx) or (vertical == 'right' and c < vx)):
            out[nhy][c] = line
    return out
'''
