program = '''def transform(grid):
    h, w = len(grid), len(grid[0])
    vertical = 'left' if len({grid[r][0] for r in range(h)}) == 1 else 'right'
    horizontal = 'top' if len(set(grid[0])) == 1 else 'bottom'
    vx = 0 if vertical == 'left' else w - 1
    hy = 0 if horizontal == 'top' else h - 1
    line = grid[hy][vx]
    fill = next(v for row in grid for v in row if v != line)
    out = [[8] * w for _ in range(h)]
    sx = 1 if vertical == 'left' else -1
    sy = 1 if horizontal == 'top' else -1
    # Original L in the field color, without its corner.
    for r in range(h):
        if r != hy:
            out[r][vx] = fill
    for c in range(w):
        if c != vx:
            out[hy][c] = fill
    # Diagonal through the outer corner diagonally opposite the L arms.
    if (horizontal, vertical) in [('bottom', 'right'), ('top', 'left')]:
        diagonal = [(r, r) for r in range(min(h, w))]
        if horizontal == 'top':
            diagonal = [(h - 1 - i, w - 1 - i) for i in range(min(h, w))]
    else:
        diagonal = [(r, w - 1 - r) for r in range(min(h, w))]
        if horizontal == 'bottom':
            diagonal = [(h - 1 - i, i) for i in range(min(h, w))]
    for r, c in diagonal:
        if (r, c) not in [diagonal[0], diagonal[-1]]:
            out[r][c] = fill
    # L translated one cell inward, without its corner.
    nvx, nhy = vx + sx, hy + sy
    for r in range(h):
        if r != nhy and ((horizontal == 'top' and r > hy) or (horizontal == 'bottom' and r < hy)):
            out[r][nvx] = line
    for c in range(w):
        if c != nvx and ((vertical == 'left' and c > vx) or (vertical == 'right' and c < vx)):
            out[nhy][c] = line
    return out
'''
